package local.pocketchat;
import android.app.Activity;import android.content.*;import android.os.*;import android.webkit.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
public class ExpandedProfileTestActivity extends Activity {
  final Handler handler=new Handler(Looper.getMainLooper());final JSONArray checks=new JSONArray();int attempts;WebView web;
  void check(String name,boolean pass){checks.put(J.obj("name",name,"pass",pass));}
  @Override public void onCreate(Bundle b){super.onCreate(b);web=new WebView(this);CookieManager.getInstance().setCookie("https://profile.fixture.invalid/","expanded_env=default-main; Secure");CookieManager.getInstance().flush();File output=new File(Profiles.context(this,7).getFilesDir(),"expanded-profile-child.json");output.delete();startActivity(new Intent(this,ExpandedProfileProbeActivity.class));handler.postDelayed(()->waitChild(output),200);}
  void waitChild(File file){if(!file.isFile()&&attempts++<60){handler.postDelayed(()->waitChild(file),100);return;}JSONObject data=new JSONObject();try(InputStream in=new FileInputStream(file)){data=J.parse(J.text(in,8000));}catch(Exception ignored){}check("Eighth profile launches in its actual owner process",data.optInt("slot")==7&&data.optString("process").endsWith(":profile7"));check("Eighth profile cannot read default cookies",!data.optBoolean("sawDefaultCookie"));String cookie=CookieManager.getInstance().getCookie("https://profile.fixture.invalid/");check("Eighth profile writes do not replace default cookies",cookie!=null&&cookie.contains("default-main")&&!cookie.contains("child7"));check("Eighth profile file remains in its own namespace",file.isFile()&&!new File(getFilesDir(),"expanded-profile-child.json").exists());try{byte[] own=new SecretStore(Profiles.context(this,7)).get("expanded-secret");check("Eighth profile sealed data uses its own key namespace",own!=null&&new String(own,StandardCharsets.UTF_8).equals("child-seven")&&new SecretStore(this).get("expanded-secret")==null);}catch(Exception e){check("Eighth profile sealed data uses its own key namespace",false);}check("Cross-process names refresh through shared catalog",Profiles.display(this,7).equals("第八环境测试"));check("Existing profiles still use the same activity mappings",Profiles.activity(0)==MainActivity.class&&Profiles.activity(1)==ProfileActivity1.class&&Profiles.activity(2)==ProfileActivity2.class);check("New service and preview route to the owning profile",Profiles.service(Profiles.context(this,7))==ProfileChatService7.class&&Profiles.preview(Profiles.context(this,7))==ProfilePreview7.class);check("All profile notification identifiers are distinct",Profiles.notification(Profiles.context(this,7),4102)!=Profiles.notification(this,4102));try{J.write(new File(getFilesDir(),"expanded-profile-results.json"),J.obj("checks",checks,"scope","Actual eighth process, CookieManager and Keystore namespaces; no account traffic").toString(2));}catch(Exception ignored){}web.destroy();}
}
